class Solution {
public:
    vector<int> diStringMatch(string s) {
        int low = 0, high = s.size();
        vector<int> res;
        res.reserve(s.size() + 1);
        for (char ch : s) {
            if (ch == 'I') {
                res.push_back(low++);
            } else {
                res.push_back(high--);
            }
        }
        res.push_back(low);
        return res;
    }
};

class Solution {
    public int[] diStringMatch(String s) {
        int n = s.length();
        int low = 0, high = n;
        int[] res = new int[n + 1];
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'I') {
                res[i] = low++;
            } else {
                res[i] = high--;
            }
        }
        res[n] = low;
        return res;
    }
}

var diStringMatch = function(s) {
    let low = 0, high = s.length;
    const res = [];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === 'I') {
            res.push(low++);
        } else {
            res.push(high--);
        }
    }
    res.push(low);
    return res;
};
